CREATE PROCEDURE [Clienti_selectrow]
	@P_45 BigInt,
	@sync_scope_local_id Int,
	@sync_scope_restore_count Int
AS
BEGIN
SELECT [side].[IdLong], [base].[IdContatto], [base].[Nome], [base].[Cognome], [base].[Indirizzo], [base].[Citta], [base].[Provincia], [base].[CAP], [base].[Telefono], [base].[Tickets], [base].[Data], [base].[Bonus], [base].[CodBar], [base].[Abilita], [base].[email], [base].[Cell], [base].[Nascita], [base].[NascOk], [base].[GiornOk], [base].[DataUltVis], [base].[OptOut], [base].[Password], [base].[FirstLogin], [base].[Note], [base].[Foto], [base].[IdTel], [base].[LastOp], [base].[Credito], [base].[NImp], [base].[F0], [base].[T0], [base].[N0], [base].[D0], [base].[F1], [base].[T1], [base].[N1], [base].[D1], [base].[TimeMod], [base].[OperMod], [base].[IdMaster1], [base].[IdMaster2], [base].[TipoDoc], [base].[Docum], [base].[Sesso], [base].[Modificato], [base].[IdLong2], [base].[EMailIsCertified], [base].[HasTelephoneNumberCorrect], [base].[UserName], [base].[TipoCard], [side].[sync_row_is_tombstone], [side].[local_update_peer_timestamp] as sync_row_timestamp, case when ([side].[update_scope_local_id] is null or [side].[update_scope_local_id] <> @sync_scope_local_id) then COALESCE([side].[restore_timestamp], [side].[local_update_peer_timestamp]) else [side].[scope_update_peer_timestamp] end as sync_update_peer_timestamp, case when ([side].[update_scope_local_id] is null or [side].[update_scope_local_id] <> @sync_scope_local_id) then case when ([side].[local_update_peer_key] > @sync_scope_restore_count) then @sync_scope_restore_count else [side].[local_update_peer_key] end else [side].[scope_update_peer_key] end as sync_update_peer_key, case when ([side].[create_scope_local_id] is null or [side].[create_scope_local_id] <> @sync_scope_local_id) then [side].[local_create_peer_timestamp] else [side].[scope_create_peer_timestamp] end as sync_create_peer_timestamp, case when ([side].[create_scope_local_id] is null or [side].[create_scope_local_id] <> @sync_scope_local_id) then case when ([side].[local_create_peer_key] > @sync_scope_restore_count) then @sync_scope_restore_count else [side].[local_create_peer_key] end else [side].[scope_create_peer_key] end as sync_create_peer_key from [Clienti] [base] right join [Clienti_tracking] [side] on [base].[IdLong] = [side].[IdLong] WHERE [side].[IdLong] = @P_45
END
